pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 depAmt, uint256 cashAmt) public {
        vm.assume(cashAmt <= address(this).balance);
        vm.assume(depAmt <= address(this).balance);

        // Deposit with fuzzed amount (may be zero in mutant)
        c.Deposit{value: depAmt}();

        // Record balance before CashOut
        uint256 balBefore = c.balances(address(this));

        // Attempt CashOut
        bool cashOk = true;
        try c.CashOut(cashAmt) {
            cashOk = true;
        } catch {
            cashOk = false;
        }

        uint256 balAfter = c.balances(address(this));

        // If CashOut succeeded, correct contract guarantees balances decreased appropriately
        assertTrue(!cashOk || balAfter <= balBefore);
    }
}

