pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 depositAmount, uint256 cashoutAmount, address caller) public {
        // Keep amounts bounded and within reasonable limits; assume caller is not zero address to avoid confusion
        vm.assume(caller != address(0));
        depositAmount = bound(depositAmount, 1 ether, 1000 ether);
        cashoutAmount = bound(cashoutAmount, 0, 1000 ether);

        // Deal ether to caller for deposit
        vm.deal(caller, depositAmount);

        // Record balance before deposit
        uint256 callerBalanceBefore = c.balances(caller);
        uint256 zeroBalanceBefore = c.balances(address(0));

        // Deposit from caller (prank sets msg.sender)
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balances after deposit
        uint256 callerBalanceAfter = c.balances(caller);
        uint256 zeroBalanceAfter = c.balances(address(0));

        // In reference contract, caller balance increases by depositAmount, zero address unchanged
        // In buggy contract, caller balance unchanged, zero address increases by depositAmount
        // If buggy, callerBalanceAfter == callerBalanceBefore and zeroBalanceAfter > zeroBalanceBefore
        // This assertion checks that after deposit, the sum of caller and zero address balances increased by depositAmount
        // Reference: (callerBalanceAfter + zeroBalanceAfter) == (callerBalanceBefore + zeroBalanceBefore) + depositAmount
        // If zero address not intended to be part of the invariant, we need to see that caller has their funds.
        // Alternatively, assert that callerBalanceAfter >= callerBalanceBefore + depositAmount (strictly true for reference, false for bug)
        assertTrue(callerBalanceAfter >= callerBalanceBefore + depositAmount);
    }
}

