pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 depositAmt, uint256 cashoutAmt, address caller) public {
        // Keep deposit above minimum and cashout within balance
        vm.assume(depositAmt >= c.MinDeposit());
        vm.assume(cashoutAmt <= depositAmt);
        // Exclude the zero address and the test contract to keep it clean
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        // Ensure no overflow
        vm.assume(depositAmt <= type(uint256).max - 1 ether);

        // Fund caller and deposit
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();

        // Try to cash out
        bool ok;
        vm.prank(caller);
        try c.CashOut(cashoutAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract must allow a cashout up to the deposited amount;
        // the mutant increases address(0) balance, leaving caller with zero,
        // so any positive cashout fails.
        assertTrue(ok);
    }
}
